<?php
require 'team_bootstrap.php'; require_role('faculty');
$fid=(int)$_SESSION['user']['id'];$teamId=(int)($_GET['team']??0);$q=$pdo->prepare("SELECT ct.*,o.id offering_id,o.subject_id,o.faculty_id,o.day_name,o.start_time,o.end_time,o.room,o.section,s.code,s.name,s.units,s.description FROM course_teams ct JOIN subject_offerings o ON o.id=ct.offering_id JOIN subjects s ON s.id=o.subject_id WHERE ct.id=? LIMIT 1");$q->execute([$teamId]);$team=$q->fetch();if(!$team||!faculty_can_access_team($pdo,$teamId,$fid)){http_response_code(403);die('You do not have access to this class team.');}
$tab=$_GET['tab']??'overview';if(!in_array($tab,['overview','materials','assignments','meetings'],true))$tab='overview';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 try{
  if($action==='create_assignment'){
   $titleA=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$due=trim($_POST['due_at']??'');$points=max(1,(int)($_POST['points']??100));$link=trim($_POST['attachment_link']??'');
   if($titleA==='')throw new Exception('Assignment title is required.'); if($link!==''&&!valid_external_link($link))throw new Exception('Please enter a valid http:// or https:// assignment link.');
   if($due!=='' ){ $dueTs=strtotime($due); if($dueTs===false) throw new Exception('Please enter a valid assignment due date and time.'); if($dueTs < time()) throw new Exception('Assignment due date and time cannot be in the past. Please choose the current date/time or a future date.'); }
   $path=null;if(!empty($_FILES['attachment_file']['name']))$path=team_upload($_FILES['attachment_file'],'uploads/assignment_materials',['pdf','doc','docx','ppt','pptx','xls','xlsx','txt','zip','jpg','jpeg','png','gif','webp'],20*1024*1024,'faculty_'.$fid.'_assignment');
   $dueDb=$due?date('Y-m-d H:i:s',strtotime($due)):null;$q=$pdo->prepare('INSERT INTO assignments(team_id,title,description,due_at,points,created_by,attachment_path,attachment_link) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$teamId,$titleA,$desc,$dueDb,$points,$fid,$path,$link?:null]);$aid=(int)$pdo->lastInsertId();team_notify_students($pdo,$teamId,'New assignment: '.$titleA,'A new assignment was posted in '.$team['code'].'.'.($dueDb?' Due '.date('M d, Y · g:i A',strtotime($dueDb)).'.':''),'Assignment');log_transaction($pdo,$fid,'Assignment Created',$titleA.' in '.$team['code'],'assignment',$aid);$success='Assignment posted to the class team.';$tab='assignments';
  } elseif($action==='create_material'){
   $titleM=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$type=$_POST['material_type']??'Material';$link=trim($_POST['link_url']??'');
   if($titleM==='')throw new Exception('Material title is required.');if(!in_array($type,['Material','Syllabus'],true))$type='Material';if($link!==''&&!valid_external_link($link))throw new Exception('Please enter a valid http:// or https:// material link.');
   $path=null;if(!empty($_FILES['material_file']['name']))$path=team_upload($_FILES['material_file'],'uploads/class_materials',['pdf','doc','docx','ppt','pptx','xls','xlsx','txt','zip','jpg','jpeg','png','gif','webp'],20*1024*1024,'team_'.$teamId.'_material');
   if(!$path&&!$link)throw new Exception('Attach a file/image or provide a link.');$q=$pdo->prepare('INSERT INTO team_materials(team_id,title,description,material_type,file_path,link_url,created_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$teamId,$titleM,$desc,$type,$path,$link?:null,$fid]);$mid=(int)$pdo->lastInsertId();team_notify_students($pdo,$teamId,'New class '.strtolower($type),$titleM.' was posted in '.$team['code'].'.','Class');log_transaction($pdo,$fid,$type.' Posted',$titleM.' in '.$team['code'],'material',$mid);$success=$type.' posted to the class team.';$tab='materials';
  } elseif($action==='delete_material'){$mid=(int)($_POST['material_id']??0);$q=$pdo->prepare('DELETE FROM team_materials WHERE id=? AND team_id=? AND created_by=?');$q->execute([$mid,$teamId,$fid]);$success=$q->rowCount()?'Class material removed.':'You can only remove materials you posted.';$tab='materials';
  } elseif($action==='create_meeting'){$titleM=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$start=trim($_POST['starts_at']??'');$duration=max(15,min(480,(int)($_POST['duration']??60)));if($titleM===''||$start==='')throw new Exception('Meeting title and start time are required.');$startDb=date('Y-m-d H:i:s',strtotime($start));$room='ETW-NUBaliwag-'.$teamId.'-'.bin2hex(random_bytes(4));$url='https://meet.jit.si/'.$room;$q=$pdo->prepare('INSERT INTO team_meetings(team_id,title,description,starts_at,duration_minutes,meeting_url,created_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$teamId,$titleM,$desc,$startDb,$duration,$url,$fid]);$mid=(int)$pdo->lastInsertId();team_notify_students($pdo,$teamId,'Online class meeting scheduled',$titleM.' for '.$team['code'].' is scheduled for '.date('M d, Y · g:i A',strtotime($startDb)).'.','Meeting');log_transaction($pdo,$fid,'Class Meeting Created',$titleM.' for '.$team['code'],'meeting',$mid);$success='Group call meeting created. Students in this team have been notified.';$tab='meetings';
  } elseif($action==='grade_submission'){$subId=(int)($_POST['submission_id']??0);$grade=$_POST['grade']===''?null:max(0,min((int)$_POST['grade'],1000));$feedback=trim($_POST['feedback']??'');$q=$pdo->prepare("SELECT asub.*,a.title,u.id student_id FROM assignment_submissions asub JOIN assignments a ON a.id=asub.assignment_id JOIN users u ON u.id=asub.student_id WHERE asub.id=? AND a.team_id=? LIMIT 1");$q->execute([$subId,$teamId]);$sub=$q->fetch();if(!$sub)throw new Exception('Submission not found.');$status=$grade===null?'Submitted':'Graded';$q=$pdo->prepare('UPDATE assignment_submissions SET grade=?,feedback=?,status=?,updated_at=NOW() WHERE id=?');$q->execute([$grade,$feedback,$status,$subId]);if($grade!==null)notify_user($pdo,(int)$sub['student_id'],'Assignment graded',$sub['title'].' has been graded by '.$_SESSION['user']['name'].'.','Assignment');$success='Submission updated.';$tab='assignments';
  } elseif($action==='delete_meeting'){$mid=(int)$_POST['meeting_id'];$q=$pdo->prepare('DELETE FROM team_meetings WHERE id=? AND team_id=? AND created_by=?');$q->execute([$mid,$teamId,$fid]);$success='Meeting removed from the class team.';$tab='meetings';}
 }catch(Throwable $ex){$error=$ex->getMessage();}
}
$aq=$pdo->prepare("SELECT a.*,COUNT(asub.id) submission_count FROM assignments a LEFT JOIN assignment_submissions asub ON asub.assignment_id=a.id WHERE a.team_id=? GROUP BY a.id ORDER BY COALESCE(a.due_at,'9999-12-31 23:59:59') ASC,a.created_at DESC");$aq->execute([$teamId]);$assignments=$aq->fetchAll();
$subs=[];$q=$pdo->prepare("SELECT asub.*,a.title,a.points,u.name,u.student_id FROM assignment_submissions asub JOIN assignments a ON a.id=asub.assignment_id JOIN users u ON u.id=asub.student_id WHERE a.team_id=? ORDER BY asub.submitted_at DESC");$q->execute([$teamId]);$subs=$q->fetchAll();
$mq=$pdo->prepare('SELECT * FROM team_meetings WHERE team_id=? ORDER BY starts_at DESC');$mq->execute([$teamId]);$meetings=$mq->fetchAll();
$matq=$pdo->prepare('SELECT * FROM team_materials WHERE team_id=? ORDER BY (material_type="Syllabus") DESC,created_at DESC');$matq->execute([$teamId]);$materials=$matq->fetchAll();
$ro=$pdo->prepare("SELECT DISTINCT u.name,u.student_id,u.email FROM enrollments e JOIN users u ON u.id=e.student_id WHERE e.offering_id=? AND e.status='approved' ORDER BY u.name");$ro->execute([(int)$team['offering_id']]);$roster=$ro->fetchAll();
require 'header.php';
?><section class="section team-page"><div class="team-hero"><div><span class="eyebrow">FACULTY CLASS TEAM</span><h2><?=e($team['code'])?> — <?=e($team['name'])?></h2><p>Section <?=e($team['section'])?> · <?=e($team['day_name'])?> <?=date('g:i A',strtotime($team['start_time']))?>–<?=date('g:i A',strtotime($team['end_time']))?> · <?=e($team['room'])?></p></div><a class="btn" href="faculty_teams.php">All Teams</a></div>
<div class="team-tabs"><a class="<?= $tab==='overview'?'active':'' ?>" href="faculty_team.php?team=<?=$teamId?>&tab=overview">Overview</a><a class="<?= $tab==='materials'?'active':'' ?>" href="faculty_team.php?team=<?=$teamId?>&tab=materials">Class Materials <span><?=count($materials)?></span></a><a class="<?= $tab==='assignments'?'active':'' ?>" href="faculty_team.php?team=<?=$teamId?>&tab=assignments">Assignments <span><?=count($assignments)?></span></a><a class="<?= $tab==='meetings'?'active':'' ?>" href="faculty_team.php?team=<?=$teamId?>&tab=meetings">Meetings <span><?=count($meetings)?></span></a></div><?php if($success):?><div class="success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="auth-alert"><?=e($error)?></div><?php endif;?>
<?php if($tab==='overview'):?><div class="team-columns"><div class="section"><div class="card-head"><h3>Class Overview</h3></div><p><?=e($team['description']?:'Manage this subject team, class materials, assignments, students, and online meetings from one place.')?></p><div class="team-stats"><div><span>Students</span><b><?=count($roster)?></b></div><div><span>Materials</span><b><?=count($materials)?></b></div><div><span>Assignments</span><b><?=count($assignments)?></b></div></div></div><div class="section"><div class="card-head"><h3>Student Roster</h3></div><div class="table-scroll"><table class="table"><tr><th>Student</th><th>ID</th><th>Email</th></tr><?php foreach($roster as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['student_id']?:'—')?></td><td><?=e($r['email'])?></td></tr><?php endforeach;?></table></div></div></div>
<?php elseif($tab==='materials'):?><div class="team-columns"><div class="section"><div class="card-head"><h3>Post Class Material</h3><p class="muted">Upload lecture files, images, links, or the syllabus for this subject.</p></div><form method="post" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="action" value="create_material"><label>Title<input name="title" placeholder="e.g. Week 4 Lecture Notes" required></label><label>Type<select name="material_type"><option>Material</option><option>Syllabus</option></select></label><label>Description<textarea name="description" rows="4" placeholder="Brief description or instructions..."></textarea></label><label>File or image<input type="file" name="material_file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,.zip,.jpg,.jpeg,.png,.gif,.webp"></label><label>Link (optional)<input type="url" name="link_url" placeholder="https://..."></label><button class="btn" type="submit">Post to Class Team</button></form></div><div class="section"><div class="card-head"><h3>Posted Materials</h3></div><?php if(!$materials):?><p class="muted">No class materials have been posted yet.</p><?php endif;?><?php foreach($materials as $m):?><div class="material-card"><div><span class="eyebrow"><?=e(strtoupper($m['material_type']))?></span><h3><?=e($m['title'])?></h3><?php if($m['description']):?><p><?=nl2br(e($m['description']))?></p><?php endif;?><small><?=date('M d, Y · g:i A',strtotime($m['created_at']))?></small></div><div class="button-group"><?php if($m['file_path']):?><a class="btn" target="_blank" href="<?=e($m['file_path'])?>">View File →</a><?php endif;?><?php if($m['link_url']):?><a class="btn secondary-btn" target="_blank" rel="noopener" href="<?=e($m['link_url'])?>">Open Link →</a><?php endif;?><form method="post"><input type="hidden" name="action" value="delete_material"><input type="hidden" name="material_id" value="<?=e($m['id'])?>"><button class="btn danger-btn small-btn" type="submit">Remove</button></form></div></div><?php endforeach;?></div></div>
<?php elseif($tab==='assignments'):?><div class="team-columns"><div class="section"><div class="card-head"><h3>Create Assignment</h3><p class="muted">Attach a file/image or reference link students can use for the task.</p></div><form method="post" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="action" value="create_assignment"><label>Assignment title<input name="title" placeholder="e.g. Laboratory Activity 1" required></label><label>Instructions<textarea name="description" rows="5" placeholder="Describe the task and requirements..."></textarea></label><div class="form-grid"><label>Due date &amp; time<input type="datetime-local" name="due_at" min="<?=e(date('Y-m-d\TH:i'))?>"><small class="muted">Current date/time or a future date only.</small></label><label>Points<input type="number" name="points" min="1" max="1000" value="100"></label></div><label>Attach file or image (optional)<input type="file" name="attachment_file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,.zip,.jpg,.jpeg,.png,.gif,.webp"></label><label>Attachment link (optional)<input type="url" name="attachment_link" placeholder="https://..."></label><button class="btn" type="submit">Post Assignment</button></form></div><div class="section"><div class="card-head"><h3>Student Submissions</h3></div><?php if(!$subs):?><p class="muted">No submissions yet.</p><?php endif;?><?php foreach($subs as $s):?><div class="submission-card"><div><b><?=e($s['name'])?></b><small><?=e($s['student_id']?:'')?></small><p><b><?=e($s['title'])?></b> · <?=e($s['status'])?> · <?=date('M d, Y · g:i A',strtotime($s['submitted_at']))?></p><?php if($s['submission_text']):?><div class="info-box"><?=nl2br(e($s['submission_text']))?></div><?php endif;?><?php if($s['file_path']):?><p><a href="<?=e($s['file_path'])?>" target="_blank">📎 Open submitted file/image →</a></p><?php endif;?><?php if($s['submission_link']):?><p><a href="<?=e($s['submission_link'])?>" target="_blank" rel="noopener">🔗 Open submitted link →</a></p><?php endif;?></div><form method="post" class="grade-form"><input type="hidden" name="action" value="grade_submission"><input type="hidden" name="submission_id" value="<?=e($s['id'])?>"><label>Grade / <?=e($s['points'])?><input type="number" name="grade" min="0" max="<?=e($s['points'])?>" value="<?=e($s['grade']??'')?>"></label><label>Feedback<textarea name="feedback" rows="3" placeholder="Feedback to student..."><?=e($s['feedback']??'')?></textarea></label><button class="btn small-btn" type="submit">Save Grade</button></form></div><?php endforeach;?></div></div>
<?php else:?><div class="team-columns"><div class="section"><div class="card-head"><h3>Create Group Call Meeting</h3><p class="muted">Creates a shared online room for students enrolled in this subject team.</p></div><form method="post" class="form-stack"><input type="hidden" name="action" value="create_meeting"><label>Meeting title<input name="title" placeholder="e.g. Week 3 Online Lecture" required></label><label>Description<textarea name="description" rows="4" placeholder="Meeting agenda or instructions..."></textarea></label><div class="form-grid"><label>Start date & time<input type="datetime-local" name="starts_at" required></label><label>Duration (minutes)<input type="number" name="duration" min="15" max="480" value="60"></label></div><button class="btn" type="submit">Create Group Meeting</button></form></div><div class="section"><div class="card-head"><h3>Scheduled Meetings</h3></div><?php if(!$meetings):?><p class="muted">No meetings yet.</p><?php endif;?><?php foreach($meetings as $m):?><div class="meeting-card"><div><span class="eyebrow">GROUP CALL</span><h3><?=e($m['title'])?></h3><p><?=e($m['description']?:'Online class meeting')?></p><small><?=date('M d, Y · g:i A',strtotime($m['starts_at']))?> · <?=e($m['duration_minutes'])?> minutes</small></div><div class="button-group"><a class="btn" target="_blank" rel="noopener" href="<?=e($m['meeting_url'])?>">Start / Join</a><form method="post"><input type="hidden" name="action" value="delete_meeting"><input type="hidden" name="meeting_id" value="<?=e($m['id'])?>"><button class="btn danger-btn small-btn" type="submit">Remove</button></form></div></div><?php endforeach;?></div></div><?php endif;?></section><?php require 'footer.php';?>
